# Cargo workspace —— 板块化架构 (架构重构 Phase 0)
# 根包 polaris-app = host (宿主, 仅装配)；各板块为 crates/ 下独立 crate。
# 跨板块只依赖 polaris-core 契约，可 `cargo test -p <板块>` 独立测试。
# ═══════════════════════════════════════════════════════════════
[workspace]
members = ["crates/*"]
resolver = "2"

[package]
name = "polaris-app"
version = "2.9.0"
description = "Polaris - 本地优先 AI 工作台 (MVP)"
authors = ["winner3388"]
edition = "2021"
# 有两个 bin(polaris-app 桌面 / polaris-server Docker)，`cargo run`(tauri dev) 默认跑桌面壳
default-run = "polaris-app"

[lib]
name = "polaris_app_lib"
crate-type = ["staticlib", "cdylib", "rlib"]

[build-dependencies]
tauri-build = { version = "2.0", features = [] }

[dependencies]
# ── 桌面外壳依赖：全部 optional，仅在 `desktop` feature 下编译 ──
# Docker(server) 构建用 `--no-default-features --features server`，不拉 tauri，
# 因此无需 Linux 上的 webkit2gtk-dev/libsoup 等系统库即可编译同一份源码。
tauri = { version = "2.1", features = [], optional = true }
tauri-plugin-dialog = { version = "2.0", optional = true }
tauri-plugin-fs = { version = "2.0", optional = true }
tauri-plugin-shell = { version = "2.0", optional = true }
# 自动更新（GitHub Releases 托管）+ 重启（更新后自重启生效）
tauri-plugin-updater = { version = "2", optional = true }
tauri-plugin-process = { version = "2", optional = true }
# 静默驻留(Tailscale 式):关窗=藏进托盘继续跑;再点桌面图标须唤起已有实例而非
# 起第二个进程(两实例会互抢 8484/网关端口、双份 claude 池)。
tauri-plugin-single-instance = { version = "2", optional = true }
# ── Docker(server) 外壳依赖：仅在 `server` feature 下编译 ──
axum = { version = "0.7", features = ["ws", "multipart"], optional = true }
tower = { version = "0.5", optional = true }
tower-http = { version = "0.6", features = ["fs", "cors", "trace"], optional = true }
futures-util = { version = "0.3", optional = true }
# 应用直投的 WebSocket/Upgrade 透传:要拿 hyper 的 OnUpgrade 扩展 + TokioIo 适配器。
# 两者本就在 axum 0.7 的依赖树里(hyper 1.x / hyper-util 0.1),显式声明不引入新编译量。
hyper = { version = "1", optional = true }
hyper-util = { version = "0.1", features = ["tokio"], optional = true }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
anyhow = "1"
# 自动更新「防卡死」用：停滞看门狗(time::sleep) + 与下载 future 竞速(select!)。
# tokio 本就随 tauri 编进来了，这里只是显式开 time/macros 两个 feature；与 Codex 那条
# 「无 tokio 的 ureq 同步流」互不影响。
tokio = { version = "1", features = ["time", "macros", "rt-multi-thread", "sync", "net", "io-util", "signal", "process"] }
# 设备联盟遥测:本机 CPU/内存/磁盘 真实采样(跨平台)。见 sysstat.rs。
sysinfo = "0.32"
walkdir = "2"
once_cell = "1"
# 把 src/templates/experts/ 整目录编进二进制：每个专家一份可编辑 .md 提示词，
# 改完重编即生效(放仓库源码、随版本走)。见 expert/expert_docs.rs。
include_dir = "0.7"
directories = "5"
parking_lot = "0.12"
regex = "1"
import { acquire, reclaim } from "../../src/models/credential-lock.ts";
import { FileCredentials } from "../../src/models/file-credentials.ts";
import { Redactor } from "../../src/models/credentials.ts";
const [mode, path] = process.argv.slice(2);
if (mode === "hold") {
  await acquire(`${path}.lock`, { timeoutMs: 2000, pollMs: 5 });
  process.send?.("held");
  setInterval(() => {}, 1000);
} else if (mode === "write") {
  await new FileCredentials(path, new Redactor(), { timeoutMs: 2000, pollMs: 5 }).modify("p",
    async () => ({ type: "api_key", key: "recovered" }));
  process.send?.("written");
} else {
  process.send?.("ready");
  process.once("message", async () => {
    process.send?.(await reclaim(`${path}.lock`, 600000));
    process.disconnect?.();
  });
}
import { mkdir, readdir, readFile, rename, rm, rmdir, writeFile, access, stat } from "node:fs/promises";
import { hostname } from "node:os";
import { randomUUID } from "node:crypto";
import { setTimeout as delay } from "node:timers/promises";
import { owner, processState, reclaimable, validOwner } from "./lock-owner.ts";

export interface LockOptions { timeoutMs: number; pollMs: number; maxHoldMs?: number }
export const DEFAULT_MAX_HOLD_MS = 600000;
// Publish a fully initialized, nonempty directory. Each generation has a unique
// child name: a delayed reaper can only rename the generation it inspected.
// Renaming that child to a unique tombstone is the atomic ownership operation.
// rmdir (never recursive removal of the live path) cannot delete a new owner.
export async function retire(lock: string, token: string): Promise<boolean> {
  const tomb = `${lock}.tomb.${randomUUID()}`;
  try { await rename(`${lock}/${token}`, tomb); }
  catch (e) { if ((e as NodeJS.ErrnoException).code === "ENOENT") return false; throw e; }
  await rmdir(lock).catch(() => undefined);
  await rm(tomb, { recursive: true, force: true });
  return true;
}
export async function reclaim(lock: string, maxHoldMs: number): Promise<boolean> {
  let names: string[];
  try { names = await readdir(lock); } catch { return false; }
  if (!names.length) { await rmdir(lock).catch(() => undefined); return false; }
  for (const token of names.filter((name) => /^owner-[\da-f-]+$/.test(name))) {
    let info: unknown;
    try { info = JSON.parse(await readFile(`${lock}/${token}/owner.json`, "utf8")); } catch { /* torn metadata */ }
    if (!validOwner(info)) {
      const modified = await stat(`${lock}/${token}`).then((s) => s.mtimeMs).catch(() => undefined);
      if (modified !== undefined && Date.now() - modified > maxHoldMs) return retire(lock, token);
      continue;
    }
    const state = info.hostname === hostname() ? await processState(info.pid) : { state: "unknown" as const };
    if (reclaimable(info, hostname(), state, Date.now(), maxHoldMs)) return retire(lock, token);
  }
  return false;
}
export async function acquire(lock: string, options: LockOptions, signal?: AbortSignal) {
  const token = `owner-${randomUUID()}`;
  const candidate = `${lock}.candidate.${randomUUID()}`;
  await mkdir(`${candidate}/${token}`, { recursive: true, mode: 0o700 });
  try {
    const info = await owner();
    const deadline = performance.now() + options.timeoutMs;
    while (true) {
      signal?.throwIfAborted();
      info.acquiredAt = Date.now();
      await writeFile(`${candidate}/${token}/owner.json`, JSON.stringify(info), { mode: 0o600 });
      try { await rename(candidate, lock); break; }
      catch (e) {
        if (!["EEXIST", "ENOTEMPTY", "EPERM", "EACCES"].includes((e as NodeJS.ErrnoException).code ?? "")) throw e;
        await reclaim(lock, options.maxHoldMs ?? DEFAULT_MAX_HOLD_MS);
        if (performance.now() >= deadline) throw new Error("CredentialStoreBusy");
        await delay(options.pollMs, undefined, { signal });
      }
    }
    return {
      async assertOwned() {
        try { await access(`${lock}/${token}/owner.json`); }
        catch { throw new Error("CredentialStoreLeaseExpired"); }
      },
      release: () => retire(lock, token),
    };
  } finally { await rm(candidate, { recursive: true, force: true }); }
}

//! Host settings: POLARIS_AGENT_CONFIG JSON, with explicit environment overrides.
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use super::BackendError;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BackendKind { Pi, ClaudeCli }
impl BackendKind {
    pub fn parse(value: &str) -> Result<Self, BackendError> {
        match value {
            "pi" => Ok(Self::Pi),
            "claude-cli" => Ok(Self::ClaudeCli),
            other => Err(BackendError::InvalidBackend(other.into())),
        }
    }
}
#[derive(Debug, Clone, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct Config {
    pub agent: Agent,
    pub agentd: Agentd,
}
impl Default for Config {
    fn default() -> Self { Self { agent: Agent::default(), agentd: Agentd::default() } }
}
#[derive(Debug, Clone, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct Agent { pub backend: String }
impl Default for Agent { fn default() -> Self { Self { backend: "pi".into() } } }
#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(default, rename_all = "camelCase", deny_unknown_fields)]
pub struct Agentd {
    pub node: PathBuf,
    pub entry: PathBuf,
    pub node_args: Vec<String>,
    pub args: Vec<String>,
    pub isolation: String,
    pub max_processes: usize,
    pub idle_ms: u64,
    pub request_timeout_ms: u64,
    /// Lost-daemon fallback: 240000 > agentd's 180000 so agentd can finish first.
    pub turn_idle_timeout_ms: u64,
    /// Hard turn limit in milliseconds; zero disables it.
    pub turn_max_ms: u64,
    #[serde(rename = "turnTimeoutMs", deserialize_with = "reject_turn_timeout", skip_serializing)]
    _legacy_turn_timeout: (),
    pub abort_timeout_ms: u64,
    pub ping_interval_ms: u64,
    pub restart_base_ms: u64,
    pub restart_max_ms: u64,
    pub restart_jitter_ms: u64,
    pub failure_threshold: u32,
    pub stable_reset_ms: u64,
    pub channel_capacity: usize,
    pub max_line_bytes: usize,
    pub delta_batch_ms: u64,
    pub write_tools: Vec<String>,
    pub readonly_tools: Vec<String>,
    /// Existing container managed by polaris-sandbox (or the server operator).
    pub sandbox_container: String,
    pub supervisor_tick_ms: u64,
    pub shutdown_timeout_ms: u64,
    pub control_poll_ms: u64,
    pub session_map: PathBuf,
    pub attachments: super::images::ImageLimits,
    pub expert_settings: PathBuf,
}
impl Default for Agentd {
    fn default() -> Self {
        Self {
            node: runtime_paths(None, None, crate::doctor::bundled::runtime_root(), development_root().as_deref()).0,
            entry: runtime_paths(None, None, crate::doctor::bundled::runtime_root(), development_root().as_deref()).1, node_args: vec![], args: vec![],
            isolation: if cfg!(feature = "desktop") { "shared" } else { "per-account" }.into(),
            max_processes: 8, idle_ms: 600_000, request_timeout_ms: 15_000,
            turn_idle_timeout_ms: 240_000, turn_max_ms: 0, _legacy_turn_timeout: (),
            abort_timeout_ms: 5_000, ping_interval_ms: 30_000,
            restart_base_ms: 200, restart_max_ms: 30_000, restart_jitter_ms: 100,
            failure_threshold: 5, stable_reset_ms: 60_000, channel_capacity: 64,
            max_line_bytes: 1_048_576, delta_batch_ms: 30,
            write_tools: vec!["write".into(), "edit".into()],
            readonly_tools: vec!["read".into(), "grep".into(), "find".into(), "ls".into(), "web_fetch".into(), "web_search".into(), "subagent".into()],
            sandbox_container: "polaris-sandbox".into(),
            supervisor_tick_ms: 10, shutdown_timeout_ms: 1000, control_poll_ms: 1,
            session_map: crate::runtime::paths::data_dir().join("agent-session-map"),
            attachments: super::images::ImageLimits::default(),
            expert_settings: crate::runtime::paths::data_file("expert-settings.json"),
        }
    }
}
/// Deterministic resolution, shared by host loading and offline path tests.
/// Explicit values always win, including a bare executable name such as `node`.
pub fn runtime_paths(
    node: Option<PathBuf>, entry: Option<PathBuf>,
    bundled: Option<&std::path::Path>, development: Option<&std::path::Path>,
) -> (PathBuf, PathBuf) {
    let node = node.or_else(|| bundled.map(|root| root.join(if cfg!(windows) {
        "node/node.exe"
    } else { "node/bin/node" })).filter(|p| p.is_file())).unwrap_or_else(|| "node".into());
    let entry = entry.or_else(|| bundled.map(|root| root.join("agentd/dist/src/main.js"))
        .filter(|p| p.is_file())).or_else(|| development.map(|root| root.join("agentd/dist/src/main.js")))
        .unwrap_or_default();
    (node, entry)
}
fn development_root() -> Option<PathBuf> {
    cfg!(debug_assertions).then(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../.."))
}
fn reject_turn_timeout<'de, D: serde::Deserializer<'de>>(_: D) -> Result<(), D::Error> {
    Err(serde::de::Error::custom(
        "InvalidAgentConfig: agentd.turnTimeoutMs was removed; use turnIdleTimeoutMs and turnMaxMs",
    ))
}
impl Config {
    pub fn load() -> anyhow::Result<Self> {
        let mut config: Self = match std::env::var_os("POLARIS_AGENT_CONFIG") {
            Some(path) => serde_json::from_slice(&std::fs::read(path)?)?,
            None => Self::default(),
        };
        if let Ok(v) = std::env::var("POLARIS_AGENT_BACKEND") { config.agent.backend = v; }
        if let Some(v) = std::env::var_os("POLARIS_AGENTD_NODE") { config.agentd.node = v.into(); }
        if let Some(v) = std::env::var_os("POLARIS_AGENTD_ENTRY") { config.agentd.entry = v.into(); }
        if let Ok(v) = std::env::var("POLARIS_AGENTD_ARGS") { config.agentd.args = serde_json::from_str(&v)?; }
        if let Ok(v) = std::env::var("POLARIS_AGENTD_NODE_ARGS") { config.agentd.node_args = serde_json::from_str(&v)?; }
        if let Ok(v) = std::env::var("POLARIS_AGENTD_ISOLATION") { config.agentd.isolation = v; }
        config.validate()?;
        Ok(config)
    }
    pub fn validate(&self) -> anyhow::Result<()> {
        BackendKind::parse(&self.agent.backend)?;
        let c = &self.agentd;
        c.attachments.validate()?;
        anyhow::ensure!(c.expert_settings.is_absolute() && c.expert_settings.file_name().is_some(),
            "InvalidAgentConfig: expertSettings must be an absolute file path");
        anyhow::ensure!(!c.sandbox_container.is_empty() && !c.sandbox_container.starts_with('-')
            && c.sandbox_container.chars().all(|ch| ch.is_ascii_alphanumeric() || "_.-".contains(ch)),
            "InvalidAgentConfig: sandboxContainer must be a Docker container name");
        anyhow::ensure!(matches!(c.isolation.as_str(), "shared" | "per-account"), "InvalidIsolation: {}", c.isolation);
        anyhow::ensure!(c.channel_capacity > 0 && c.max_line_bytes > 0 && c.max_processes > 0,
            "InvalidAgentConfig: capacities must be positive");
        anyhow::ensure!(c.turn_idle_timeout_ms > 0, "InvalidAgentConfig: agentd.turnIdleTimeoutMs must be positive");
        anyhow::ensure!(c.request_timeout_ms > 0 && c.abort_timeout_ms > 0
            && c.ping_interval_ms > 0 && c.idle_ms > 0 && c.delta_batch_ms > 0
            && c.supervisor_tick_ms > 0 && c.control_poll_ms > 0 && c.shutdown_timeout_ms > 0
            && c.stable_reset_ms > 0 && c.failure_threshold > 0 && c.restart_base_ms > 0 && c.restart_max_ms >= c.restart_base_ms,
            "InvalidAgentConfig: timeouts and restart bounds must be positive");
        Ok(())
    }
}
