import { mkdirSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import {
  createAgentSession, DefaultResourceLoader, SessionManager, SettingsManager,
  type ExtensionFactory,
} from "@earendil-works/pi-coding-agent";
import type { Config } from "../config/schema.ts";
import type { Models } from "../models/runtime.ts";
import type { SessionOptions } from "../protocol/schema.ts";
import { contextFiles, expandPath } from "../extensions/resources.ts";
import { activateTools, profileTools } from "./options.ts";
import { DaemonError } from "../protocol/errors.ts";

export async function createSession(
  config: Config, models: Models, factories: ExtensionFactory[], sessionId?: string, requestedCwd?: string, options: SessionOptions = {}, mandatoryFactories: (cwd: string) => ExtensionFactory[] = () => [], existingManager?: SessionManager,
) {
  const runtime = models.runtime;
  const tools = profileTools(config, options.toolProfile ?? config.defaultToolProfile);
  mkdirSync(config.sessionDir, { recursive: true });
  const cwd = resolve(requestedCwd ?? process.cwd());
  let manager: SessionManager;
  if (existingManager) manager = existingManager;
  else if (sessionId) {
    // Exact lookup, never treat an untrusted session id as a filesystem path.
    if (!/^[a-zA-Z0-9-]+$/.test(sessionId)) throw new DaemonError("INVALID_SESSION_ID", "Invalid session id");
    const path = (await SessionManager.listAll(config.sessionDir)).find((info) => info.id === sessionId)?.path;
    if (!path) throw new DaemonError("SESSION_NOT_FOUND", "Persisted session not found");
    manager = SessionManager.open(path, config.sessionDir, requestedCwd ? cwd : undefined);
  } else manager = SessionManager.create(cwd, config.sessionDir);
  try {
    if (!statSync(manager.getCwd()).isDirectory()) throw new Error();
  } catch {
    throw new DaemonError("INVALID_CWD", "Working directory does not exist");
  }
  const model = runtime.getModel((options.model ?? config.defaultModel).provider, (options.model ?? config.defaultModel).id);
  if (!model) throw new DaemonError("MODEL_NOT_FOUND", "Configured default model does not exist");
  const settingsManager = SettingsManager.inMemory({
    shellPath: config.shellPath || undefined,
    compaction: config.compaction, retry: config.retry, cacheWarming: "off",
  });
  const agentDir = join(config.sessionDir, ".resources");
  const resourceLoader = new DefaultResourceLoader({
    cwd: manager.getCwd(), agentDir, settingsManager,
    // Only host-assembled executable extensions. Standard AGENTS.md/skills still load.
    noExtensions: true, noThemes: true,
    extensionFactories: [...(config.extensions.enabled ? factories : []), ...mandatoryFactories(manager.getCwd())],
    additionalSkillPaths: config.skills.paths.map(expandPath),
    agentsFilesOverride: (base) => contextFiles(manager.getCwd(), base),
  });
  await resourceLoader.reload();
  const { session } = await createAgentSession({
    cwd: manager.getCwd(), agentDir, model, modelRuntime: runtime,
    thinkingLevel: options.thinkingLevel ?? config.thinkingLevel,
    // Register the configured universe so idle profile changes can enable tools.
    tools: [...new Set(Object.values(config.toolProfiles).flat())],
    settingsManager, sessionManager: manager, resourceLoader,
  });
  try {
    await session.bindExtensions({ mode: "rpc" });
    activateTools(session, tools);
    return session;
  } catch (error) {
    session.dispose();
    throw error;
  }
}

#[cfg(not(feature = "desktop"))]
fn dispatch_chat_and_services(cmd: &str, a: &Args, app: AppHandle) -> Result<Value, String> {
    use crate::*;
    match cmd {
        // ── Chat (sync 部分) ──
        "chat_permission_respond" => {
            let response = serde_json::from_value(a.get("response").cloned()
                .ok_or("缺少参数 response")?).map_err(|e| format!("授权参数解析失败: {e}"))?;
