        } else { uid.into() };
        let permit = interconnect::risk::authorize_on(&actor_uid, &actor_node, uid, host,
            &s_of(value, "operation"), &s_of(value, "digest"), &s_of(value, "nonce"))?;
        Ok(json!({"permit":authority::sign_document("PRISK1", &permit)?}))
    }).await
