def encrypt(source, destination, mode, recipient, timeout_secs):
    if mode == 'age':
        command = [tool('age'), '--encrypt', '--recipient', recipient]
    elif mode == 'gpg':
        command = [tool('gpg'), '--no-options', '--batch', '--no-tty', '--output', '-',
