            with closing(sqlite3.connect(normalized / 'collab.db')) as dst:
                src.backup(dst)
        check_db(normalized / 'collab.db')
        (normalized / PAYLOAD[1]).write_bytes((source / PAYLOAD[1]).read_bytes())
        manifest = {'format': 1, 'authorityImage': image, 'sha256': {}}
        for name in PAYLOAD:
